def emit():
    seen = set()
    cards = []
    for row in ROWS:
        (id_, name, season, franchise, pos, tier, nba_id, arch,
         scoring, three, mid, paint, defense, rebound, passing, speed, strength, stamina, iq, clutch, steal, block,
         paint_fg, mid_fg, three_fg, ft, growth, gs, ego, team_p, fiery, calm, tags) = row
        if id_ in seen:
            continue
        seen.add(id_)
        cards.append({
            "id": id_, "name": name, "season": season, "team": franchise, "pos": pos,
            "tier": tier, "nbaId": nba_id, "arch": arch,
            "scoring": scoring, "three": three, "mid": mid, "paint": paint,
            "defense": defense, "rebound": rebound, "pass": passing, "speed": speed,
            "strength": strength, "stamina": stamina, "iq": iq, "clutch": clutch,
            "steal": steal, "block": block,
            "paintFg": paint_fg, "midFg": mid_fg, "threeFg": three_fg, "ft": ft,
            "growth": growth, "gs": gs, "ego": ego, "teamP": team_p, "fiery": fiery, "calm": calm,
            "tags": tags,
        })

    out = Path(__file__).resolve().parents[1] / "js" / "data" / "players.js"
    lines = []
    lines.append('import { nbaPhoto, avatarFallback } from "./photo.js";')
    lines.append("")
    lines.append("export const HIDDEN_TIERS = {")
    lines.append('  undrafted_gleague: { weight: 18, label: "落选+短期合同+D联盟" },')
    lines.append('  water_cooler: { weight: 14, label: "饮水机管理员" },')
    lines.append('  bench: { weight: 16, label: "bench player" },')
    lines.append('  starter: { weight: 18, label: "starters" },')
    lines.append('  star: { weight: 12, label: "球星" },')
    lines.append('  allstar: { weight: 10, label: "全明星" },')
    lines.append('  hof: { weight: 6, label: "名人堂" },')
    lines.append('  nba50: { weight: 4, label: "NBA 50 大巨星" },')
    lines.append('  superstar: { weight: 2, label: "超级巨星" },')
    lines.append("};")
    lines.append("")
    lines.append("function card(p) {")
    lines.append("  const photo = p.nbaId ? nbaPhoto(p.nbaId) : avatarFallback(p.name);")
    lines.append("  return {")
    lines.append("    id: p.id, name: p.name, season: p.season, team: p.team, pos: p.pos,")
    lines.append("    nbaId: p.nbaId ?? null, photo,")
    lines.append("    scoring: p.scoring, three: p.three, mid: p.mid, paint: p.paint,")
    lines.append("    defense: p.defense, rebound: p.rebound, pass: p.pass, speed: p.speed,")
    lines.append("    strength: p.strength, stamina: p.stamina, iq: p.iq, clutch: p.clutch,")
    lines.append("    steal: p.steal ?? 50, block: p.block ?? 40,")
    lines.append("    paintFg: p.paintFg, midFg: p.midFg, threeFg: p.threeFg, ft: p.ft,")
    lines.append("    personality: { ego: p.ego, team: p.teamP, fiery: p.fiery, calm: p.calm },")
    lines.append("    growth: p.growth, growthSpeed: p.gs, archetype: p.arch,")
    lines.append("    hiddenTier: p.tier, tags: p.tags || [],")
    lines.append("  };")
    lines.append("}")
    lines.append("")
    lines.append(f"// Auto-generated: {len(cards)} season cards (1950s–2020s legends + role players)")
    lines.append("const RAW = " + json.dumps(cards, ensure_ascii=False, indent=2) + ";")
    lines.append("")
    lines.append("export const PLAYERS = RAW.map(card);")
    lines.append("")
    lines.append("export function clonePlayer(p) {")
    lines.append("  return structuredClone(p);")
    lines.append("}")
    lines.append("")
    lines.append("export function overall(p) {")
    lines.append("  const w =")
    lines.append("    p.scoring * 0.16 +")
    lines.append("    p.defense * 0.12 +")
    lines.append("    p.pass * 0.09 +")
    lines.append("    p.rebound * 0.09 +")
    lines.append("    (p.steal || 50) * 0.05 +")
    lines.append("    (p.block || 40) * 0.05 +")
    lines.append("    p.speed * 0.07 +")
    lines.append("    p.strength * 0.07 +")
    lines.append("    p.iq * 0.1 +")
    lines.append("    p.clutch * 0.08 +")
    lines.append("    p.stamina * 0.05 +")
    lines.append("    ((p.three + p.mid + p.paint) / 3) * 0.07;")
    lines.append("  return Math.round(w);")
    lines.append("}")
    lines.append("")
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"Wrote {len(cards)} players -> {out}")

if __name__ == "__main__":
    emit()
